const G=9.8,TG=[30,45,18],R=1.4,N=60;
const rad=a=>a*Math.PI/180;
function shot(a,v){const r=rad(a),vx=v*Math.cos(r),vy=v*Math.sin(r),T=2*vy/G;return{vx,vy,T,d:vx*T,H:vy*vy/(2*G)};}
function pos(s,t){return[s.vx*t,Math.max(0,s.vy*t-G*t*t/2)+R,0];}
function pts(c,f){const s=shot(c.a,c.v),n=Math.round(f*N),p=[];for(let k=0;k<=n;k++)p.push(pos(s,s.T*k/N));p.push(pos(s,s.T*f));return p;}
export function initialState(){return{fly:false,f:0,cur:null,prev:null,shots:0,hits:0,last:null};}
export function reduce({state,event,inputs}){const st=state;
if(event.type==='action'&&event.action==='launch'){if(st.fly||st.hits>=3||st.shots>=10)return st;return{...st,fly:true,f:0,prev:st.cur,cur:{a:inputs.angle,v:inputs.speed}};}
if(event.type==='step'&&st.fly){const f=Math.min(1,st.f+1/N);if(f<1)return{...st,f};const s=shot(st.cur.a,st.cur.v),miss=s.d-TG[st.hits],hit=Math.abs(miss)<=1.5;return{...st,fly:false,f:1,shots:st.shots+1,hits:st.hits+(hit?1:0),last:{d:s.d,miss,T:s.T,H:s.H,hit}};}
return st;}
export function evaluate({inputs,state}){const st=state,th=rad(inputs.angle-90),nodes={};
nodes.pivot={quaternion:[0,0,Math.sin(th/2),Math.cos(th/2)]};
const ti=Math.min(st.hits,2);nodes.tgt={position:[TG[ti],0,0],visible:st.hits<3};
if(st.cur){const s=shot(st.cur.a,st.cur.v);nodes.ballN={position:pos(s,s.T*st.f)};nodes.trailN={visible:true,points:pts(st.cur,st.f)};}else{nodes.ballN={position:[0,R,0]};nodes.trailN={visible:false,points:[]};}
nodes.ghostN=st.prev?{visible:true,points:pts(st.prev,1)}:{visible:false,points:[]};
const ro={used:st.shots,hitsR:st.hits};const L=st.last;
if(L){const m=Math.abs(L.miss),side=L.miss<0?'short':'long';ro.dist=L.d;ro.miss=(L.hit?'Hit, ':'Miss, ')+m.toFixed(1)+' m '+side;ro.ftime=L.T;ro.hmax=L.H;}
let status='playing',msg;
if(st.hits>=3){status='won';msg='You hit all 3 targets in '+st.shots+' launches!';}
else if(st.shots>=10&&!st.fly){status='lost';msg='Out of launches: '+st.hits+' of 3 targets hit.';}
else if(st.fly)msg='Ball in flight...';
else if(L)msg=(L.hit?'Hit! Next target at ':'Missed by '+Math.abs(L.miss).toFixed(1)+' m. Adjust and aim again at ')+TG[ti]+' m.';
else msg='Target at 30 m. Set angle and speed, then press Launch.';
return{nodes,readouts:ro,goal:{status,message:msg}};}
